AbstractField* RFQRequest::msgType() {
  return &beginString_;
}

void RFQRequest::writeUnmapped() {
  valBeg_ = 24;
  valLim_ = 24;
  int bodyBeg = 24;
  valLim_ = rFQReqID_.write(valLim_);
  valLim_ = relatedSymGroup6_.write(valLim_);
  valLim_ = subscriptionRequestType_.write(valLim_);
  int bodyLim = valLim_;
  AbstractMessage::writeUnmapped(bodyLength_, bodyLim - bodyBeg, beginString_, checkSum_);
}

int RFQRequest::writeMapped() {
  int fldLim = AbstractMessage::writeMapped();
  calcAndWriteBodyLengthMapped(bodyLength_, beginString_);
  calcAndWriteCheckSum(checkSum_);
  return fldLim;
}

